import unittest

from model_runtime.heavy_review import _validate_review


class HeavyReviewTests(unittest.TestCase):
    def test_pass_is_overridden_when_verifier_failed(self):
        review = {"verdict": "pass", "summary": "ok", "issues": [], "tests_to_run": []}
        result = _validate_review(review, {"ok": False})
        self.assertEqual(result["verdict"], "corrections")
        self.assertTrue(result["issues"])

    def test_pass_kept_when_verifier_ok(self):
        review = {"verdict": "pass", "summary": "ok", "issues": [], "tests_to_run": []}
        result = _validate_review(review, {"ok": True})
        self.assertEqual(result["verdict"], "pass")


if __name__ == "__main__":
    unittest.main()
